<?php
require_once __DIR__.'/includes/bootstrap.php';$token=(string)($_GET['token']??$_POST['token']??'');$tokenHash=hash('sha256',$token);$st=$GLOBALS['pdo']->prepare('SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1');$st->execute([$tokenHash]);$reset=$st->fetch();$error='';$done=false;
if(!$reset){$error='Tautan reset tidak valid atau sudah kedaluwarsa.';}elseif($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$password=(string)($_POST['password']??'');$confirm=(string)($_POST['password_confirm']??'');if(strlen($password)<10)$error='Password minimal 10 karakter.';elseif($password!==$confirm)$error='Konfirmasi password tidak sama.';else{$GLOBALS['pdo']->beginTransaction();try{$GLOBALS['pdo']->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$reset['user_id']]);$GLOBALS['pdo']->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$reset['user_id']]);$GLOBALS['pdo']->commit();session_regenerate_id(true);$done=true;audit_log('password.reset_completed','user',(int)$reset['user_id']);}catch(Throwable $e){$GLOBALS['pdo']->rollBack();$error='Password belum dapat diperbarui.';}}}
require_once __DIR__.'/includes/header.php';$layout='marketing';datanix_header('Password baru','',$layout);
?>
<div class="auth-page"><div class="form-card"><a class="brand-lockup mb-4" href="<?=e(url('index.php'))?>"><img src="<?=e(url('assets/img/datanix-mark.svg'))?>" width="34" height="34" alt=""><span>datanix</span></a><h1>Password baru.</h1><?php if($done):?><div class="alert alert-success">Password berhasil diperbarui.</div><a class="btn btn-primary w-100" href="<?=e(url('login.php'))?>">Masuk</a><?php else:?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($reset):?><form method="post"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><div class="mb-3"><label class="form-label">Password baru</label><input class="form-control" type="password" name="password" minlength="10" autocomplete="new-password" required></div><div class="mb-4"><label class="form-label">Konfirmasi password</label><input class="form-control" type="password" name="password_confirm" minlength="10" autocomplete="new-password" required></div><button class="btn btn-primary w-100">Simpan password</button></form><?php else:?><a href="<?=e(url('forgot-password.php'))?>">Minta tautan baru</a><?php endif;?><?php endif;?></div></div>
